export default class ResizeObserverService{constructor(selector){this.targetElement=document.querySelector(selector);if(!this.targetElement){throw new Error(`Element with selector ${selector} not found.`)}this._inputResizedTimeout=0;this.observerForNewElements=new MutationObserver((()=>{this.targetElement.querySelectorAll(".dyjsform_input").forEach((targetInput=>{if(!targetInput.__mutationObserver){const observer=new MutationObserver((()=>{clearTimeout(this._inputResizedTimeout);this._inputResizedTimeout=setTimeout((()=>{this.inputResized(selector,targetInput)}),100)}));observer.observe(targetInput,{attributes:true,attributeFilter:["style"]});targetInput.__mutationObserver=observer}}))}));this.observerForNewElements.observe(this.targetElement,{childList:true,subtree:true})}inputResized(selector,targetInput){const eventName=`${selector}.ResizeObserverService.inputResized`;const event=new CustomEvent(eventName,{detail:{element:targetInput,message:"Element resized"}});targetInput.dispatchEvent(event);console.log(`Event triggered: ${eventName}`)}disconnect(){this.observerForNewElements.disconnect()}}